import { useLiveQuery } from 'dexie-react-hooks'
import './experience.css'
import { initializeAppearance } from './lib/experience'
import BackgroundAlerts from './components/BackgroundAlerts'
import ExperienceBar from './components/ExperienceBar'
import { routeAllowed } from './lib/permissions'
const Operations = lazy(() => import('./screens/Operations'))
import { createContext, useContext, useEffect, useMemo, useState, lazy, Suspense } from 'react'
import {
  LayoutDashboard, Car, ShoppingCart, KeyRound, Users, FileText, Calculator,
  TrendingUp, Settings, LogOut, Menu, X, Wifi, WifiOff, Download, ChevronsUpDown, Bell,
  SquareParking, Cloud,
} from 'lucide-react'
import { startParkingSync } from './lib/parkingSync'
import { startOcrSync } from './lib/ocrSync'
import { db, seedDemo } from './lib/db'
import { ensureParkingSetup, seedParkingDemo } from './lib/parking'
import { useRoute, navigate } from './lib/router'
import { ToastProvider, Badge } from './components/UI'
import Auth from './screens/Auth'
const Dashboard = lazy(() => import('./screens/Dashboard'))
const Stock = lazy(() => import('./screens/Stock'))
const Sales = lazy(() => import('./screens/Sales'))
const NewSale = lazy(() => import('./screens/NewSale'))
const Rentals = lazy(() => import('./screens/Rentals'))
const Clients = lazy(() => import('./screens/Clients'))
const Billing = lazy(() => import('./screens/Billing'))
const Accounting = lazy(() => import('./screens/Accounting'))
const Stats = lazy(() => import('./screens/Stats'))
const Admin = lazy(() => import('./screens/Admin'))
const Parking = lazy(() => import('./screens/Parking'))
const Sync = lazy(() => import('./screens/Sync'))
import { initials, classNames } from './lib/format'

const ExperienceHub = lazy(() => import('./screens/ExperienceHub'))
initializeAppearance()

export const AppCtx = createContext(null)
export const useApp = () => useContext(AppCtx)

const NAV = [
  { group: 'Pilotage', items: [
    { to: '/dashboard', label: 'Tableau de bord', icon: LayoutDashboard },
    { to: '/experience', label: 'Expérience & finances', icon: Settings },
    { to: '/statistiques', label: 'Statistiques', icon: TrendingUp, admin: true },
  ] },
  { group: 'Exploitation', items: [
    { to: '/stock', label: 'Stock & véhicules', icon: Car },
    { to: '/stationnement', label: 'Stationnement', icon: SquareParking },
    { to: '/exploitation', label: 'Équipe & exploitation', icon: Users },
    { to: '/ventes', label: 'Ventes', icon: ShoppingCart },
    { to: '/locations', label: 'Locations', icon: KeyRound },
    { to: '/clients', label: 'Clients', icon: Users },
  ] },
  { group: 'Finance', items: [
    { to: '/facturation', label: 'Facturation', icon: FileText },
    { to: '/comptabilite', label: 'Comptabilité', icon: Calculator, admin: true },
  ] },
  { group: 'Configuration', items: [
    { to: '/admin', label: 'Administration', icon: Settings, admin: true },
  ] },
]

const TITLES = {
  experience: ['Expérience & finances', 'Accessibilité, budgets, notifications et sécurité'],
  dashboard: ['Tableau de bord', 'Vue consolidée de votre activité'],
  stock: ['Stock & véhicules', 'Inventaire, fiches techniques et disponibilité'],
  stationnement: ['Stationnement', 'Plan des places, tickets horaires et réservations'],
  exploitation: ['Équipe & exploitation', 'Planning, présence, caisse et incidents'],
  sync: ['Synchronisation', 'Réplication cloud Supabase et temps réel'],
  ventes: ['Ventes', 'Historique, factures et encaissements'],
  locations: ['Locations', 'Contrats en cours, retours et cautions'],
  clients: ['Clients', 'Particuliers, entreprises et encours'],
  facturation: ['Facturation', 'Factures, reçus et documents PDF'],
  comptabilite: ['Comptabilité', 'Charges, résultat et bilan simplifié'],
  statistiques: ['Statistiques', 'Performance commerciale et équipe'],
  admin: ['Administration', 'Parking, employés et paramètres'],
}

function useOnline() {
  const [online, setOnline] = useState(navigator.onLine)
  useEffect(() => {
    const on = () => setOnline(true)
    const off = () => setOnline(false)
    window.addEventListener('online', on)
    window.addEventListener('offline', off)
    return () => { window.removeEventListener('online', on); window.removeEventListener('offline', off) }
  }, [])
  return online
}

function useInstallPrompt() {
  const [evt, setEvt] = useState(null)
  useEffect(() => {
    const h = (e) => { e.preventDefault(); setEvt(e) }
    window.addEventListener('beforeinstallprompt', h)
    return () => window.removeEventListener('beforeinstallprompt', h)
  }, [])
  const install = async () => {
    if (!evt) return false
    evt.prompt()
    const res = await evt.userChoice
    setEvt(null)
    return res.outcome === 'accepted'
  }
  return { canInstall: !!evt, install }
}

function Shell({ session, onLogout, onSwitchLot }) {
  useEffect(() => startOcrSync(session.lot.id), [session.lot.id])
  useEffect(() => startParkingSync(session.lot.id), [session.lot.id])
  const route = useRoute()
  const online = useOnline()
  const { canInstall, install } = useInstallPrompt()
  const [menuOpen, setMenuOpen] = useState(false)
  const [lotMenu, setLotMenu] = useState(false)
  const isAdmin = session.user.role === 'admin'
  const ADMIN_ONLY = { comptabilite: 1, statistiques: 1, admin: 1, sync: 1 }
  const [title, sub] = (!isAdmin && ADMIN_ONLY[route.segment])
    ? TITLES.dashboard
    : (TITLES[route.segment] || TITLES.dashboard)

  useEffect(() => { setMenuOpen(false); setLotMenu(false) }, [route.path])

  const items = NAV.map((g) => ({ ...g, items: g.items.filter((i) => (!i.admin || isAdmin) && routeAllowed(session.user, i.to.slice(1))) })).filter((g) => g.items.length)

  const page = useMemo(() => {
    if (!routeAllowed(session.user, route.segment)) return <div className="card"><h2>Accès restreint</h2><p>Votre rôle ne permet pas l’accès à cette section.</p></div>
    switch (route.segment) {
      case 'experience': return <ExperienceHub />
      case 'exploitation': return <Operations />
      case 'stock': return <Stock />
      case 'stationnement': return <Parking />
      case 'sync': return <Sync />
      case 'ventes':
        return route.parts[1] === 'nouvelle' ? <NewSale /> : <Sales />
      case 'locations': return <Rentals />
      case 'clients': return <Clients />
      case 'facturation': return <Billing />
      case 'comptabilite': return isAdmin ? <Accounting /> : <Dashboard />
      case 'statistiques': return isAdmin ? <Stats /> : <Dashboard />
      case 'admin': return isAdmin ? <Admin /> : <Dashboard />
      default: return session.user.role === 'agent' ? <Operations /> : <Dashboard />
    }
  }, [route.segment, route.parts.join('/'), isAdmin, session.user.role, session.user.active])

  return (
    <div className="shell">
      <a className="skip-link" href="#main-content" onClick={(e)=>{e.preventDefault();document.getElementById('main-content')?.focus()}}>Aller au contenu principal</a>
      <aside aria-label="Navigation principale" className={classNames('sidebar', menuOpen && 'open')}>
        <div className="brand">
          <div className="brand-logo">
            {session.lot.logo ? <img src={session.lot.logo} alt="logo" /> : <Car size={20} />}
          </div>
          <div className="brand-txt">
            <strong>MON PARKING</strong>
            <span>{session.lot.name}</span>
          </div>
          <button className="icon-btn" style={{ marginLeft: 'auto', display: menuOpen ? 'grid' : 'none' }} onClick={() => setMenuOpen(false)}>
            <X />
          </button>
        </div>

        <div style={{ overflowY: 'auto', flex: 1, margin: '0 -4px', padding: '0 4px' }}>
          {items.map((g) => (
            <div key={g.group}>
              <div className="nav-group-label">{g.group}</div>
              {g.items.map((i) => (
                <a key={i.to} className={classNames('nav-item', route.path.startsWith(i.to) && 'on')} href={`#${i.to}`}>
                  <i.icon />
                  <span>{i.label}</span>
                </a>
              ))}
            </div>
          ))}
        </div>

        <div className="sidebar-foot">
          <div className="row" style={{ marginBottom: 10, gap: 6 }}>
            <Badge tone={online ? 'ok' : 'danger'} dot>{online ? 'En ligne' : 'Hors ligne'}</Badge>
            <Badge tone="acc">{isAdmin ? 'Administrateur' : 'Employé'}</Badge>
          </div>
          <button className="user-pill" onClick={onLogout}>
            <div className="avatar">{initials(session.user.name)}</div>
            <div className="meta">
              <b>{session.user.name}</b>
              <span>@{session.user.username} · Déconnexion</span>
            </div>
            <LogOut style={{ width: 15, height: 15, color: 'var(--muted)', marginLeft: 'auto' }} />
          </button>
        </div>
      </aside>

      <div className="main">
        <header className="topbar">
          <button className="icon-btn" aria-label="Ouvrir le menu de navigation" onClick={() => setMenuOpen(true)} style={{ display: 'grid' }}>
            <Menu />
          </button>
          <div className="page-title">
            {title}
            <small>{sub}</small>
          </div>
          <div className="topbar-actions">
            {canInstall && (
              <button className="install-pill" onClick={install} title="Installer l'application sur cet appareil">
                <Download style={{ width: 13, height: 13 }} /> Installer
              </button>
            )}
            <div style={{ position: 'relative' }}>
              <button className="btn btn-sm btn-ghost" onClick={() => setLotMenu((v) => !v)}>
                <Car style={{ width: 13, height: 13 }} />
                <span style={{ maxWidth: 150, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{session.lot.name}</span>
                <ChevronsUpDown style={{ width: 12, height: 12 }} />
              </button>
              {lotMenu && (
                <div style={{
                  position: 'absolute', right: 0, top: 'calc(100% + 8px)', minWidth: 260, zIndex: 60,
                  background: '#111826', border: '1px solid var(--line-2)', borderRadius: 13, padding: 7,
                  boxShadow: 'var(--shadow)',
                }}>
                  <div className="tiny mut" style={{ padding: '6px 9px' }}>MES PARKINGS</div>
                  {session.lots.map((l) => (
                    <button key={l.id} className="nav-item" style={{ width: '100%', border: 0, background: l.id === session.lot.id ? 'var(--acc-soft)' : 'transparent' }}
                      onClick={() => { setLotMenu(false); onSwitchLot(l) }}>
                      <span style={{ width: 22, height: 22, borderRadius: 6, overflow: 'hidden', background: '#1b2434', display: 'grid', placeItems: 'center', flex: '0 0 auto' }}>
                        {l.logo ? <img src={l.logo} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} /> : <Car size={12} />}
                      </span>
                      <span style={{ flex: 1, textAlign: 'left', fontSize: 12.5 }}>{l.name}</span>
                      {l.id === session.lot.id && <span className="tiny" style={{ color: 'var(--acc)' }}>actif</span>}
                    </button>
                  ))}
                  {isAdmin && (
                    <a className="nav-item" href="#/admin" style={{ fontSize: 12.5 }}>
                      <Settings style={{ width: 14, height: 14 }} /> Gérer les parkings
                    </a>
                  )}
                </div>
              )}
            </div>
            <Badge tone={online ? 'ok' : 'danger'}>{online ? <Wifi style={{ width: 11, height: 11 }} /> : <WifiOff style={{ width: 11, height: 11 }} />}</Badge>
          </div>
        </header>

        <BackgroundAlerts lot={session.lot} user={session.user} />
        <ExperienceBar lot={session.lot} user={session.user} />
        <main className="content" id="main-content" tabIndex="-1"><Suspense fallback={<p role="status">Chargement de la section…</p>}>{page}</Suspense></main>

        <nav aria-label="Navigation mobile" className="mobile-bottom">
          {[
            { to: '/dashboard', label: 'Accueil', icon: LayoutDashboard },
            { to: '/stock', label: 'Stock', icon: Car },
            { to: '/stationnement', label: 'Parking', icon: SquareParking },
            { to: '/ventes/nouvelle', label: 'Vendre', icon: ShoppingCart },
            { to: '/facturation', label: 'Factures', icon: FileText },
            { to: isAdmin ? '/admin' : '/experience', label: isAdmin ? 'Admin' : 'Réglages', icon: Settings },
          ].map((i) => (
            <a key={i.to} href={`#${i.to}`} className={route.path === i.to ? 'on' : ''}>
              <i.icon />
              {i.label}
            </a>
          ))}
        </nav>
      </div>
    </div>
  )
}

export default function App() {
  const [session, setSession] = useState(null)
  const [ready, setReady] = useState(false)
  const liveUser = useLiveQuery(() => session?.user?.id ? db.users.get(session.user.id) : null, [session?.user?.id], null)
  useEffect(() => {
    if (!session || !liveUser) return
    if (!liveUser.active) { localStorage.removeItem('mp_session'); setSession(null); return }
    if (liveUser.role !== session.user.role || liveUser.name !== session.user.name) setSession((s) => s ? { ...s, user: liveUser } : null)
  }, [liveUser?.active, liveUser?.role, liveUser?.name, session?.user?.id])

  useEffect(() => {
    ;(async () => {
      try { await seedDemo() } catch (e) { console.warn('seed', e) }
      const saved = localStorage.getItem('mp_session')
      if (saved) {
        try {
          const { userId, lotId } = JSON.parse(saved)
          const user = await db.users.get(userId)
          const lot = await db.lots.get(lotId)
          if (user?.active && lot) await hydrate(user, lot)
        } catch { /* ignore */ }
      }
      setReady(true)
    })()
  }, [])

  const hydrate = async (user, lot) => {
    try {
      await ensureParkingSetup(lot)
      await seedParkingDemo(lot)
    } catch (e) { console.warn('parking setup', e) }
    const rows = await db.users.where('username').equals(user.username).toArray()
    const lots = (await db.lots.bulkGet(rows.map((r) => r.lotId))).filter(Boolean)
    localStorage.setItem('mp_session', JSON.stringify({ userId: user.id, lotId: lot.id }))
    setSession({ user, lot, lots })
  }

  const handleLogin = async (user, lot) => { await hydrate(user, lot) }

  const handleLogout = () => {
    localStorage.removeItem('mp_session')
    setSession(null)
    navigate('/dashboard')
  }

  const switchLot = async (lot) => {
    const rows = await db.users.where('username').equals(session.user.username).toArray()
    const match = rows.find((r) => r.lotId === lot.id)
    if (!match) return
    localStorage.setItem('mp_session', JSON.stringify({ userId: match.id, lotId: lot.id }))
    setSession({ user: match, lot, lots: session.lots })
  }

  if (!ready) {
    return (
      <div style={{ display: 'grid', placeItems: 'center', minHeight: '100dvh', color: 'var(--muted)', fontSize: 13 }}>
        <div style={{ textAlign: 'center' }}>
          <div className="brand-logo" style={{ margin: '0 auto 14px', width: 46, height: 46 }}><Car size={22} /></div>
          Chargement de MON PARKING…
        </div>
      </div>
    )
  }

  return (
    <ToastProvider>
      {session ? (
        <AppCtx.Provider value={{ ...session, isAdmin: session.user.role === 'admin', onSwitchLot: switchLot, refresh: () => hydrate(session.user, session.lot) }}>
          <Shell session={session} onLogout={handleLogout} onSwitchLot={switchLot} />
        </AppCtx.Provider>
      ) : (
        <Auth onLogin={handleLogin} />
      )}
    </ToastProvider>
  )
}

import { useEffect, useRef, useState } from 'react'
import { fmtMoney } from '../lib/format'

/* ---------- animated area/line chart ---------- */
export function AreaChart({ data, height = 190, color = '#c6f24e', color2 = '#4cc9f0', format = (v) => v, showGrid = true }) {
  const [hover, setHover] = useState(null)
  const w = 640
  const h = height
  const pad = { l: 6, r: 6, t: 14, b: 22 }
  const max = Math.max(1, ...data.map((d) => d.value))
  const iw = w - pad.l - pad.r
  const ih = h - pad.t - pad.b
  const x = (i) => pad.l + (data.length === 1 ? iw / 2 : (i / (data.length - 1)) * iw)
  const y = (v) => pad.t + ih - (v / max) * ih
  const pts = data.map((d, i) => [x(i), y(d.value)])
  const line = pts.map((p, i) => `${i === 0 ? 'M' : 'L'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ')
  const area = `${line} L${x(data.length - 1)},${pad.t + ih} L${x(0)},${pad.t + ih} Z`
  const id = `g${color.replace('#', '')}`

  return (
    <div style={{ position: 'relative' }}>
      <svg viewBox={`0 0 ${w} ${h}`} className="chart-svg" style={{ height }} preserveAspectRatio="none"
        onMouseLeave={() => setHover(null)}
        onMouseMove={(e) => {
          const r = e.currentTarget.getBoundingClientRect()
          const rel = ((e.clientX - r.left) / r.width) * w
          let best = 0
          pts.forEach((p, i) => { if (Math.abs(p[0] - rel) < Math.abs(pts[best][0] - rel)) best = i })
          setHover(best)
        }}
      >
        <defs>
          <linearGradient id={id} x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor={color} stopOpacity="0.32" />
            <stop offset="100%" stopColor={color} stopOpacity="0" />
          </linearGradient>
        </defs>
        {showGrid && [0, 0.25, 0.5, 0.75, 1].map((t) => (
          <line key={t} x1={pad.l} x2={w - pad.r} y1={pad.t + ih * t} y2={pad.t + ih * t} stroke="rgba(255,255,255,0.07)" strokeDasharray="3 5" />
        ))}
        <path d={area} fill={`url(#${id})`} />
        <path d={line} fill="none" stroke={color} strokeWidth="2.4" strokeLinejoin="round" strokeLinecap="round"
          style={{ filter: `drop-shadow(0 4px 12px ${color}55)` }} />
        {pts.map((p, i) => (
          <g key={i}>
            <circle cx={p[0]} cy={p[1]} r={hover === i ? 5 : 2.6} fill={hover === i ? color : '#0a0f18'} stroke={color} strokeWidth="2" />
          </g>
        ))}
        {hover !== null && (
          <line x1={pts[hover][0]} x2={pts[hover][0]} y1={pad.t} y2={pad.t + ih} stroke="rgba(255,255,255,0.22)" />
        )}
        {data.map((d, i) => (
          <text key={d.label + i} x={x(i)} y={h - 5} fill="#6c7890" fontSize="10" textAnchor="middle">{d.label}</text>
        ))}
      </svg>
      {hover !== null && (
        <div style={{
          position: 'absolute', left: `${(x(hover) / w) * 100}%`, top: 0, transform: 'translateX(-50%)',
          background: '#131b28', border: '1px solid rgba(255,255,255,0.16)', borderRadius: 9, padding: '5px 9px',
          fontSize: 11, pointerEvents: 'none', whiteSpace: 'nowrap', zIndex: 3,
        }}>
          <b style={{ color }}>{format(data[hover].value)}</b>
          <span className="mut"> · {data[hover].label}</span>
        </div>
      )}
    </div>
  )
}

/* ---------- grouped bars ---------- */
export function Bars({ data, height = 195, currency = 'XOF' }) {
  const max = Math.max(1, ...data.flatMap((d) => [d.a || 0, d.b || 0]))
  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'flex-end', gap: 10, height, padding: '0 2px' }}>
        {data.map((d, i) => (
          <div key={d.label + i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6, height: '100%', justifyContent: 'flex-end' }}>
            <div style={{ display: 'flex', alignItems: 'flex-end', gap: 3, height: '100%', width: '100%', justifyContent: 'center' }}>
              <div title={`${d.label} : ${fmtMoney(d.a, currency)}`} style={{
                width: '38%', maxWidth: 16, borderRadius: '5px 5px 2px 2px',
                height: `${Math.max(2, (d.a / max) * 100)}%`,
                background: 'linear-gradient(180deg,#c6f24e,#8fd21f)', transition: 'height .5s cubic-bezier(.2,.9,.3,1)',
              }} />
              {d.b !== undefined && (
                <div title={`${d.label} : ${fmtMoney(d.b, currency)}`} style={{
                  width: '38%', maxWidth: 16, borderRadius: '5px 5px 2px 2px',
                  height: `${Math.max(2, (d.b / max) * 100)}%`,
                  background: 'linear-gradient(180deg,#4cc9f0,#2b8fb3)', transition: 'height .5s cubic-bezier(.2,.9,.3,1)',
                }} />
              )}
            </div>
            <span style={{ fontSize: 10, color: '#6c7890' }}>{d.label}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

/* ---------- donut ---------- */
export function Donut({ data, size = 168, thickness = 22, centerLabel, centerValue }) {
  const total = data.reduce((a, b) => a + b.value, 0) || 1
  const r = (size - thickness) / 2
  const c = 2 * Math.PI * r
  let offset = 0
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 18, flexWrap: 'wrap' }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ flex: '0 0 auto' }}>
        <g transform={`rotate(-90 ${size / 2} ${size / 2})`}>
          <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(255,255,255,0.07)" strokeWidth={thickness} />
          {data.map((d, i) => {
            const len = (d.value / total) * c
            const el = (
              <circle key={i} cx={size / 2} cy={size / 2} r={r} fill="none" stroke={d.color} strokeWidth={thickness}
                strokeDasharray={`${Math.max(0, len - 2)} ${c}`} strokeDashoffset={-offset} strokeLinecap="round"
                style={{ transition: 'stroke-dasharray .6s ease' }} />
            )
            offset += len
            return el
          })}
        </g>
        <text x="50%" y="46%" textAnchor="middle" fill="#e9eef7" fontSize="17" fontWeight="700" fontFamily="Space Grotesk, sans-serif">
          {centerValue}
        </text>
        <text x="50%" y="58%" textAnchor="middle" fill="#8b97ad" fontSize="9.5">{centerLabel}</text>
      </svg>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 8, flex: 1, minWidth: 120 }}>
        {data.map((d, i) => (
          <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: 12 }}>
            <i style={{ width: 8, height: 8, borderRadius: 3, background: d.color, flex: '0 0 auto' }} />
            <span className="mut" style={{ flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{d.label}</span>
            <b className="num">{Math.round((d.value / total) * 100)}%</b>
          </div>
        ))}
      </div>
    </div>
  )
}

/* ---------- sparkline ---------- */
export function Spark({ values, color = '#c6f24e', height = 30 }) {
  const max = Math.max(1, ...values)
  const w = 90
  const d = values.map((v, i) => `${i === 0 ? 'M' : 'L'}${(i / Math.max(1, values.length - 1)) * w},${height - (v / max) * height}`).join(' ')
  return (
    <svg viewBox={`0 0 ${w} ${height}`} width={w} height={height} style={{ overflow: 'visible' }}>
      <path d={d} fill="none" stroke={color} strokeWidth="1.8" strokeLinecap="round" />
    </svg>
  )
}

/* ---------- animated counter ---------- */
export function Counter({ value, duration = 900, format = (v) => Math.round(v).toLocaleString('fr-FR') }) {
  const [display, setDisplay] = useState(0)
  const from = useRef(0)
  useEffect(() => {
    if(document.documentElement.dataset.motion==='reduced'||window.matchMedia('(prefers-reduced-motion: reduce)').matches){setDisplay(Number(value)||0);from.current=Number(value)||0;return}
    const start = performance.now()
    const a = from.current
    const b = Number(value) || 0
    let raf
    const tick = (t) => {
      const p = Math.min(1, (t - start) / duration)
      const eased = 1 - Math.pow(1 - p, 3)
      setDisplay(a + (b - a) * eased)
      if (p < 1) raf = requestAnimationFrame(tick)
      else from.current = b
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [value, duration])
  return <>{format(display)}</>
}

