import { useMemo, useState } from 'react'
import { useLiveQuery } from 'dexie-react-hooks'
import { Users, Plus, Search, Pencil, Trash2, Phone, Mail, MapPin, Building2, User, ReceiptText } from 'lucide-react'
import { db } from '../lib/db'
import { saveClient, deleteClient } from '../lib/admin'
import { useApp } from '../App'
import { Card, CardHead, Badge, Modal, Confirm, Empty, Field, Input, Select, useToast, IconBtn } from '../components/UI'
import { fmtMoney, fmtDate, initials } from '../lib/format'

export default function Clients() {
  const { lot, isAdmin } = useApp()
  const cur = lot.currency
  const toast = useToast()
  const clients = useLiveQuery(() => db.clients.where('lotId').equals(lot.id).toArray(), [lot.id], [])
  const sales = useLiveQuery(() => db.sales.where('lotId').equals(lot.id).toArray(), [lot.id], [])
  const [q, setQ] = useState('')
  const [open, setOpen] = useState(false)
  const [editing, setEditing] = useState(null)
  const [toDelete, setToDelete] = useState(null)
  const [f, setF] = useState({ name: '', phone: '', email: '', address: '', type: 'particulier', taxId: '' })

  const enriched = useMemo(() => clients.map((c) => {
    const list = sales.filter((s) => s.clientId === c.id)
    return {
      ...c,
      count: list.length,
      revenue: list.reduce((a, s) => a + Number(s.total || 0), 0),
      due: list.reduce((a, s) => a + Math.max(0, Number(s.total || 0) - Number(s.paid || 0)), 0),
      last: list.sort((a, b) => new Date(b.date) - new Date(a.date))[0]?.date,
    }
  }).filter((c) => !q.trim() || `${c.name} ${c.phone} ${c.email}`.toLowerCase().includes(q.toLowerCase()))
    .sort((a, b) => b.revenue - a.revenue), [clients, sales, q])

  const openForm = (c) => {
    setEditing(c || null)
    setF(c ? { name: c.name, phone: c.phone || '', email: c.email || '', address: c.address || '', type: c.type || 'particulier', taxId: c.taxId || '' } : { name: '', phone: '', email: '', address: '', type: 'particulier', taxId: '' })
    setOpen(true)
  }

  const submit = async () => {
    if (!f.name.trim()) { toast.err('Le nom est requis.'); return }
    await saveClient(lot.id, { ...f, name: f.name.trim() }, editing?.id)
    toast.ok(editing ? 'Client mis à jour.' : 'Client ajouté.')
    setOpen(false)
  }

  const totalReceivable = enriched.reduce((a, c) => a + c.due, 0)

  return (
    <div className="stack">
      <div className="row">
        <div>
          <h1 style={{ fontSize: 22 }}>Clients</h1>
          <p className="mut" style={{ margin: '3px 0 0', fontSize: 12.5 }}>
            {clients.length} fiche(s) · {fmtMoney(totalReceivable, cur)} d’encours total
          </p>
        </div>
        <span className="spacer" />
        <button className="btn btn-primary" onClick={() => openForm(null)}><Plus /> Nouveau client</button>
      </div>

      <Card>
        <div className="search-box" style={{ maxWidth: 380 }}>
          <Search /><input className="input" placeholder="Nom, téléphone, e-mail…" value={q} onChange={(e) => setQ(e.target.value)} />
        </div>
      </Card>

      {enriched.length === 0 ? (
        <Card><Empty icon={Users} title="Aucun client" text="Créez des fiches clients pour suivre leurs achats et encours."
          action={<button className="btn btn-primary" onClick={() => openForm(null)}><Plus /> Nouveau client</button>} /></Card>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill,minmax(290px,1fr))', gap: 14 }}>
          {enriched.map((c) => (
            <Card key={c.id} style={{ padding: 16 }}>
              <div className="row" style={{ marginBottom: 10 }}>
                <div className="avatar" style={{ width: 38, height: 38 }}>{initials(c.name)}</div>
                <div style={{ minWidth: 0, flex: 1 }}>
                  <div style={{ fontWeight: 600, fontSize: 13.5, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{c.name}</div>
                  <Badge tone={c.type === 'entreprise' ? 'info' : 'default'}>{c.type === 'entreprise' ? <><Building2 style={{ width: 10, height: 10 }} /> Entreprise</> : <><User style={{ width: 10, height: 10 }} /> Particulier</>}</Badge>
                </div>
                {isAdmin && (
                  <div style={{ display: 'flex', gap: 4 }}>
                    <IconBtn title="Modifier" onClick={() => openForm(c)}><Pencil /></IconBtn>
                    <IconBtn title="Supprimer" onClick={() => setToDelete(c)}><Trash2 /></IconBtn>
                  </div>
                )}
              </div>
              <div style={{ display: 'grid', gap: 4, fontSize: 11.5, color: 'var(--muted)' }}>
                {c.phone && <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}><Phone style={{ width: 11, height: 11 }} />{c.phone}</span>}
                {c.email && <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}><Mail style={{ width: 11, height: 11 }} />{c.email}</span>}
                {c.address && <span style={{ display: 'flex', alignItems: 'center', gap: 6 }}><MapPin style={{ width: 11, height: 11 }} />{c.address}</span>}
              </div>
              <div style={{ display: 'flex', gap: 12, marginTop: 12, paddingTop: 11, borderTop: '1px solid var(--line)' }}>
                <div style={{ flex: 1 }}>
                  <div className="tiny mut">{c.count} achat(s)</div>
                  <div style={{ fontFamily: 'Space Grotesk', fontWeight: 700, fontSize: 13, color: 'var(--acc)' }}>{fmtMoney(c.revenue, cur)}</div>
                </div>
                <div style={{ textAlign: 'right' }}>
                  <div className="tiny mut">Encours</div>
                  <div style={{ fontFamily: 'Space Grotesk', fontWeight: 700, fontSize: 13, color: c.due > 0 ? 'var(--danger)' : 'var(--ok)' }}>{fmtMoney(c.due, cur)}</div>
                </div>
              </div>
              {c.last && <div className="tiny mut" style={{ marginTop: 7 }}>Dernier achat : {fmtDate(c.last)}</div>}
            </Card>
          ))}
        </div>
      )}

      <Modal open={open} onClose={() => setOpen(false)} title={editing ? 'Modifier le client' : 'Nouveau client'} icon={Users}
        footer={<><button className="btn btn-ghost" onClick={() => setOpen(false)}>Annuler</button>
          <button className="btn btn-primary" onClick={submit}>Enregistrer</button></>}>
        <Field label="Nom / raison sociale *"><Input value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} placeholder="Fatou Bamba" /></Field>
        <div className="grid2">
          <Field label="Téléphone"><Input value={f.phone} onChange={(e) => setF({ ...f, phone: e.target.value })} placeholder="+225 …" /></Field>
          <Field label="E-mail"><Input value={f.email} onChange={(e) => setF({ ...f, email: e.target.value })} /></Field>
        </div>
        <div className="grid2">
          <Field label="Type"><Select value={f.type} onChange={(e) => setF({ ...f, type: e.target.value })}>
            <option value="particulier">Particulier</option><option value="entreprise">Entreprise</option>
          </Select></Field>
          <Field label="N° fiscal / IFU"><Input value={f.taxId} onChange={(e) => setF({ ...f, taxId: e.target.value })} /></Field>
        </div>
        <Field label="Adresse"><Input value={f.address} onChange={(e) => setF({ ...f, address: e.target.value })} /></Field>
      </Modal>

      <Confirm open={!!toDelete} danger title="Supprimer le client"
        text={`Supprimer la fiche de ${toDelete?.name} ? Les factures existantes conserveront les informations du client.`}
        confirmLabel="Supprimer"
        onCancel={() => setToDelete(null)}
        onConfirm={async () => { await deleteClient(toDelete.id); setToDelete(null); toast.ok('Client supprimé.') }} />
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import { useLiveQuery } from 'dexie-react-hooks'
import {
  Car, User, CreditCard, Check, ArrowLeft, ArrowRight, Search, Plus, FileText,
  KeyRound, ShoppingCart, AlertTriangle, CalendarDays, Percent,
} from 'lucide-react'
import { db, createSale, nowIso } from '../lib/db'
import { saveClient } from '../lib/admin'
import { useApp } from '../App'
import { Card, CardHead, Badge, Empty, Field, Input, Select, useToast, Seg, Modal } from '../components/UI'
import { CarArt } from './Stock'
import { fmtMoney, fmtDate, daysBetween, addDays } from '../lib/format'
import { buildInvoice, buildReceipt } from '../lib/pdf'
import { navigate } from '../lib/router'

const STEPS = ['Véhicule', 'Client', 'Conditions', 'Validation']

export default function NewSale() {
  const { lot, user, isAdmin } = useApp()
  const cur = lot.currency
  const toast = useToast()
  const vehicles = useLiveQuery(() => db.vehicles.where('lotId').equals(lot.id).toArray(), [lot.id], [])
  const clients = useLiveQuery(() => db.clients.where('lotId').equals(lot.id).toArray(), [lot.id], [])
  const stock = useMemo(() => vehicles.filter((v) => v.status === 'stock'), [vehicles])

  const [step, setStep] = useState(0)
  const [q, setQ] = useState('')
  const [vehicleId, setVehicleId] = useState(null)
  const [clientId, setClientId] = useState(null)
  const [type, setType] = useState('vente')
  const [price, setPrice] = useState(0)
  const [discount, setDiscount] = useState(0)
  const [vatRate, setVatRate] = useState(lot.vatRate ?? 18)
  const [paid, setPaid] = useState(0)
  const [paidTouched, setPaidTouched] = useState(false)
  const [method, setMethod] = useState('espèces')
  const [notes, setNotes] = useState('')
  const [rentalStart, setRentalStart] = useState(new Date().toISOString().slice(0, 10))
  const [rentalEnd, setRentalEnd] = useState(addDays(new Date(), 7).toISOString().slice(0, 10))
  const [deposit, setDeposit] = useState(0)
  const [clientModal, setClientModal] = useState(false)
  const [newClient, setNewClient] = useState({ name: '', phone: '', email: '', address: '', type: 'particulier', taxId: '' })
  const [busy, setBusy] = useState(false)
  const [done, setDone] = useState(null)

  const vehicle = stock.find((v) => v.id === vehicleId) || null
  const client = clients.find((c) => c.id === clientId) || null
  const days = Math.max(1, daysBetween(rentalStart, rentalEnd))


  useEffect(() => {
    if (!vehicle) return
    if (type === 'vente') {
      setPrice(vehicle.price)
      setPaid(vehicle.price)
    } else {
      const total = (vehicle.rentPriceDaily || 0) * days
      setPrice(total)
      setPaid(total)
      setDeposit(vehicle.price * 0.15)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [vehicleId, type, days])

  const subtotal = Math.max(0, Number(price) - Number(discount))
  const vatAmount = Math.round(subtotal * (Number(vatRate) / 100))
  const total = subtotal + vatAmount
  const due = Math.max(0, total - Number(paid))

  useEffect(() => {
    if (!paidTouched) setPaid(total)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [total, paidTouched])

  const filteredStock = stock.filter((v) =>
    !q.trim() || `${v.brand} ${v.model} ${v.plate} ${v.category}`.toLowerCase().includes(q.toLowerCase())
  )

  const createClientInline = async () => {
    if (!newClient.name.trim()) { toast.err('Le nom du client est requis.'); return }
    const id = await saveClient(lot.id, { ...newClient, name: newClient.name.trim() })
    setClientId(id)
    setClientModal(false)
    setNewClient({ name: '', phone: '', email: '', address: '', type: 'particulier', taxId: '' })
    toast.ok('Client créé.')
  }

  const finalize = async (printMode) => {
    if (!vehicle) return toast.err('Sélectionnez un véhicule.')
    if (total <= 0) return toast.err('Le montant total doit être supérieur à 0.')
    setBusy(true)
    try {
      const sale = await createSale({
        lotId: lot.id, type, vehicleId: vehicle.id,
        vehicleSnapshot: {
          brand: vehicle.brand, model: vehicle.model, year: vehicle.year, plate: vehicle.plate,
          vin: vehicle.vin, mileage: vehicle.mileage, category: vehicle.category,
          purchasePrice: vehicle.purchasePrice,
        },
        clientId: client?.id || null,
        clientSnapshot: client
          ? { name: client.name, phone: client.phone, email: client.email, address: client.address, taxId: client.taxId }
          : { name: 'Client comptant', phone: '', email: '', address: '', taxId: '' },
        userId: user.id, userName: user.name,
        date: nowIso(), price: Number(price), discount: Number(discount), vatRate: Number(vatRate),
        subtotal, vatAmount, total: Number(total), paid: Number(paid), paymentMethod: method,
        notes, rentalStart: type === 'location' ? new Date(rentalStart).toISOString() : null,
        rentalEnd: type === 'location' ? new Date(rentalEnd).toISOString() : null,
        rentalDays: type === 'location' ? days : 0,
        deposit: type === 'location' ? Number(deposit) : 0,
      })
      setDone(sale)
      toast.ok(`Transaction enregistrée · ${sale.invoiceNumber}`)
      if (printMode) {
        const doc = await buildInvoice(sale, lot)
        doc.save(`${sale.invoiceNumber}.pdf`)
      }
    } catch (e) {
      toast.err(e.message || 'Enregistrement impossible.')
    }
    setBusy(false)
  }

  const download = async (kind) => {
    if (!done) return
    const doc = kind === 'receipt' ? await buildReceipt(done, lot) : await buildInvoice(done, lot)
    doc.save(`${kind === 'receipt' ? done.receiptNumber : done.invoiceNumber}.pdf`)
  }

  if (done) {
    return (
      <div className="stack" style={{ maxWidth: 720, margin: '0 auto' }}>
        <Card style={{ textAlign: 'center', padding: 34 }}>
          <div style={{ width: 62, height: 62, borderRadius: '50%', background: 'var(--acc-soft)', border: '1px solid rgba(198,242,78,0.4)', display: 'grid', placeItems: 'center', margin: '0 auto 16px', color: 'var(--acc)' }}>
            <Check style={{ width: 30, height: 30 }} />
          </div>
          <h1 style={{ fontSize: 23 }}>Transaction enregistrée</h1>
          <p className="mut" style={{ fontSize: 13, marginTop: 6 }}>
            {done.invoiceNumber} · {done.receiptNumber}<br />
            Stock mis à jour automatiquement — véhicule désormais « {type === 'vente' ? 'vendu' : 'en location'} ».
          </p>
          <div style={{ display: 'flex', gap: 14, justifyContent: 'center', margin: '20px 0', flexWrap: 'wrap' }}>
            <div><div className="tiny mut">Total TTC</div><div style={{ fontFamily: 'Space Grotesk', fontSize: 20, fontWeight: 700, color: 'var(--acc)' }}>{fmtMoney(total, cur)}</div></div>
            <div><div className="tiny mut">Encaissé</div><div style={{ fontFamily: 'Space Grotesk', fontSize: 20, fontWeight: 700 }}>{fmtMoney(paid, cur)}</div></div>
            {due > 0 && <div><div className="tiny mut">Reste dû</div><div style={{ fontFamily: 'Space Grotesk', fontSize: 20, fontWeight: 700, color: 'var(--danger)' }}>{fmtMoney(due, cur)}</div></div>}
          </div>
          <div className="row" style={{ justifyContent: 'center' }}>
            <button className="btn btn-ghost" onClick={() => download('receipt')}><FileText style={{ width: 14, height: 14 }} /> Reçu PDF</button>
            <button className="btn btn-ghost" onClick={() => download('invoice')}><FileText style={{ width: 14, height: 14 }} /> Facture PDF</button>
            <button className="btn btn-primary" onClick={() => navigate('/ventes')}>Voir les ventes <ArrowRight style={{ width: 14, height: 14 }} /></button>
          </div>
        </Card>
        <Card>
          <CardHead title="Nouvelle opération" />
          <p className="mut" style={{ fontSize: 12.5, marginTop: 0 }}>Vous pouvez enchaîner immédiatement sur une autre vente ou location.</p>
          <button className="btn btn-ghost" onClick={() => {
            setDone(null); setStep(0); setVehicleId(null); setClientId(null); setPrice(0); setPaid(0); setDiscount(0); setNotes('')
          }}><Plus style={{ width: 14, height: 14 }} /> Créer une autre transaction</button>
        </Card>
      </div>
    )
  }

  return (
    <div className="stack">
      <div className="row">
        <button className="icon-btn" onClick={() => navigate('/ventes')}><ArrowLeft /></button>
        <div>
          <h1 style={{ fontSize: 22 }}>Nouvelle transaction</h1>
          <p className="mut" style={{ margin: '3px 0 0', fontSize: 12.5 }}>Facture et reçu générés automatiquement</p>
        </div>
        <span className="spacer" />
        <Seg value={type} onChange={(v) => { setType(v) }} options={[
